macro_rules! deps {
    () => {
        Sealed!();
        Config!();
        DecodeError!();
        Reader!();
        WithContext!();
    };
}

macro_rules! Decoder {
    () => {
        deps!();
        # [doc = " Any source that can decode basic types. This type is most notably implemented for [Decoder]."] pub trait Decoder : Sealed { # [doc = " The concrete [Reader] type"] type R : Reader ; # [doc = " The concrete [Config] type"] type C : Config ; # [doc = " The decoding context type"] type Context ; # [doc = " Returns the decoding context"] fn context (& mut self) -> & mut Self :: Context ; # [doc = " Wraps decoder with a context"] fn with_context < C > (& mut self , context : C) -> WithContext < Self , C > { WithContext { decoder : self , context , } } # [doc = " Returns a mutable reference to the reader"] fn reader (& mut self) -> & mut Self :: R ; # [doc = " Returns a reference to the config"] fn config (& self) -> & Self :: C ; # [doc = " Claim that `n` bytes are going to be read from the decoder."] # [doc = " This can be used to validate `Configuration::Limit<N>()`."] fn claim_bytes_read (& mut self , n : usize) -> Result < () , DecodeError > ; # [doc = " Claim that we're going to read a container which contains `len` entries of `T`."] # [doc = " This will correctly handle overflowing if `len * size_of::<T>() > usize::max_value`"] fn claim_container_read < T > (& mut self , len : usize) -> Result < () , DecodeError > { if < Self :: C as InternalLimitConfig > :: LIMIT . is_some () { match len . checked_mul (core :: mem :: size_of :: < T > ()) { Some (val) => self . claim_bytes_read (val) , None => Err (DecodeError :: LimitExceeded) , } } else { Ok (()) } } # [doc = " Notify the decoder that `n` bytes are being reclaimed."] # [doc = ""] # [doc = " When decoding container types, a typical implementation would claim to read `len * size_of::<T>()` bytes."] # [doc = " This is to ensure that bincode won't allocate several GB of memory while constructing the container."] # [doc = ""] # [doc = " Because the implementation claims `len * size_of::<T>()`, but then has to decode each `T`, this would be marked"] # [doc = " as double. This function allows us to un-claim each `T` that gets decoded."] # [doc = ""] # [doc = " We cannot check if `len * size_of::<T>()` is valid without claiming it, because this would mean that if you have"] # [doc = " a nested container (e.g. `Vec<Vec<T>>`), it does not know how much memory is already claimed, and could easily"] # [doc = " allocate much more than the user intends."] # [doc = " ```"] # [doc = " # use bincode::de::{Decode, Decoder};"] # [doc = " # use bincode::error::DecodeError;"] # [doc = " # struct Container<T>(Vec<T>);"] # [doc = " # impl<T> Container<T> {"] # [doc = " #     fn with_capacity(cap: usize) -> Self {"] # [doc = " #         Self(Vec::with_capacity(cap))"] # [doc = " #     }"] # [doc = " #     "] # [doc = " #     fn push(&mut self, t: T) {"] # [doc = " #         self.0.push(t);"] # [doc = " #     }"] # [doc = " # }"] # [doc = " impl<Context, T: Decode<Context>> Decode<Context> for Container<T> {"] # [doc = "     fn decode<D: Decoder<Context = Context>>(decoder: &mut D) -> Result<Self, DecodeError> {"] # [doc = "         let len = u64::decode(decoder)?;"] # [doc = "         let len: usize = len.try_into().map_err(|_| DecodeError::OutsideUsizeRange(len))?;"] # [doc = "         // Make sure we don't allocate too much memory"] # [doc = "         decoder.claim_bytes_read(len * core::mem::size_of::<T>());"] # [doc = ""] # [doc = "         let mut result = Container::with_capacity(len);"] # [doc = "         for _ in 0..len {"] # [doc = "             // un-claim the memory"] # [doc = "             decoder.unclaim_bytes_read(core::mem::size_of::<T>());"] # [doc = "             result.push(T::decode(decoder)?)"] # [doc = "         }"] # [doc = "         Ok(result)"] # [doc = "     }"] # [doc = " }"] # [doc = " impl<'de, Context, T: bincode::BorrowDecode<'de, Context>> bincode::BorrowDecode<'de, Context> for Container<T> {"] # [doc = "     fn borrow_decode<D: bincode::de::BorrowDecoder<'de, Context = Context>>("] # [doc = "         decoder: &mut D,"] # [doc = "     ) -> core::result::Result<Self, bincode::error::DecodeError> {"] # [doc = "         let len = u64::borrow_decode(decoder)?;"] # [doc = "         let len: usize = len.try_into().map_err(|_| DecodeError::OutsideUsizeRange(len))?;"] # [doc = "         // Make sure we don't allocate too much memory"] # [doc = "         decoder.claim_bytes_read(len * core::mem::size_of::<T>());"] # [doc = ""] # [doc = "         let mut result = Container::with_capacity(len);"] # [doc = "         for _ in 0..len {"] # [doc = "             // un-claim the memory"] # [doc = "             decoder.unclaim_bytes_read(core::mem::size_of::<T>());"] # [doc = "             result.push(T::borrow_decode(decoder)?)"] # [doc = "         }"] # [doc = "         Ok(result)"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] fn unclaim_bytes_read (& mut self , n : usize) ; }
    };
}

Decoder!()